insert into bar_achievement_launch(singleton) values(true);
insert into achievements(id,photo_url,title,description,requirement,category,availability,future_tag,reward_currency,reward_stars,reward_experience,reward_tokens,sort_order) values
('bar-1-character','/achievements/bar/darts-wins-v1.webp','Победы в дартс · Дарья','Дротики на стойке, мишень свободна. Сыграй с Дарьей и собери свои победы в барном дартсе.','Победить в этой игре 1 раз против персонажа «Дарья».','bar','active',null,0,3,3,0,31000),
('bar-1-online','/achievements/bar/darts-wins-v1.webp','Победы в дартс · Онлайн','У каждого соперника свой прицел. Подстраивайся под ход партии и забирай победы у реальных игроков.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31001),
('bar-2-character','/achievements/bar/darts-streak-v1.webp','Победная серия в дартс · Дарья','Держи руку ровно от партии к партии. Дарья снова выходит к мишени, а твоя победная серия продолжается.','Выиграть 2 партии подряд против персонажа «Дарья».','bar','active',null,0,5,5,0,31002),
('bar-2-online','/achievements/bar/darts-streak-v1.webp','Победная серия в дартс · Онлайн','Новый соперник, новый матч — и снова твоя победа. Сохрани точность на целую серию партий.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31003),
('bar-3-character','/achievements/bar/darts-180-v1.webp','Большой заход · Дарья','Три дротика сходятся в утроении двадцатки. Поймай это движение и повтори подход, в котором каждый бросок попадает куда надо.','Набрать 180 очков тремя дротиками за один свой ход.','bar','active',null,0,10,10,0,31004),
('bar-3-online','/achievements/bar/darts-180-v1.webp','Большой заход · Онлайн','Три дротика сходятся в утроении двадцатки. Поймай это движение и повтори подход, в котором каждый бросок попадает куда надо.','Набрать 180 очков тремя дротиками за один свой ход.','bar','active',null,0,10,10,0,31005),
('bar-4-character','/achievements/bar/darts-perfect-v1.webp','Идеальная партия · Дарья','Девять дротиков — и счёт закрыт. Идеальный лег, который хочется пересмотреть бросок за броском.','Законно завершить партию с 501 очка за девять дротиков.','bar','active',null,0,50,50,0,31006),
('bar-4-online','/achievements/bar/darts-perfect-v1.webp','Идеальная партия · Онлайн','Девять дротиков — и счёт закрыт. Идеальный лег, который хочется пересмотреть бросок за броском.','Законно завершить партию с 501 очка за девять дротиков.','bar','active',null,0,50,50,0,31007),
('bar-5-character','/achievements/bar/darts-rematch-v1.webp','Реванш в дартс · Дарья','Прошлая партия осталась за Дарьей. Собери дротики, вернись к мишени и забери следующую.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31008),
('bar-5-online','/achievements/bar/darts-rematch-v1.webp','Реванш в дартс · Онлайн','Поражение ещё свежо, а соперник уже ждёт у мишени. В следующей встрече поменяйся с ним местами.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31009),
('bar-6-character','/achievements/bar/pool-wins-v1.webp','Победы в бильярд · Вероника','Сукно ровное, кий готов, Вероника у стола. Продумывай удары и пополняй счёт своих побед.','Победить в этой игре 1 раз против персонажа «Вероника».','bar','active',null,0,3,3,0,31010),
('bar-6-online','/achievements/bar/pool-wins-v1.webp','Победы в бильярд · Онлайн','У стола встретились два игрока со своим почерком. Навяжи свой темп и доведи партию до победного шара.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31011),
('bar-7-character','/achievements/bar/pool-streak-v1.webp','Победная серия в бильярд · Вероника','Вероника не отдаст стол без борьбы. Сохрани точность на несколько партий и продолжи свою серию.','Выиграть 2 партии подряд против персонажа «Вероника».','bar','active',null,0,5,5,0,31012),
('bar-7-online','/achievements/bar/pool-streak-v1.webp','Победная серия в бильярд · Онлайн','Соперники меняются, а стол снова остаётся за тобой. Проведи победную серию от первого удара до последнего шара.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31013),
('bar-8-character','/achievements/bar/pool-close-v1.webp','На тоненького · Вероника','Один шар отделяет победу от поражения. Соберись у стола и доведи эту напряжённую партию до конца.','Победить с разницей ровно в один обычный шар.','bar','active',null,0,5,5,0,31014),
('bar-8-online','/achievements/bar/pool-close-v1.webp','На тоненького · Онлайн','Один шар отделяет победу от поражения. Соберись у стола и доведи эту напряжённую партию до конца.','Победить с разницей ровно в один обычный шар.','bar','active',null,0,5,5,0,31015),
('bar-9-character','/achievements/bar/pool-margin-v1.webp','С запасом · Вероника','Оставь сопернику шары на столе, а себе — уверенную победу. Чем больше перевес, тем выше уровень достижения.','Победить с разницей ровно в 3 обычных шара.','bar','active',null,0,3,3,0,31016),
('bar-9-online','/achievements/bar/pool-margin-v1.webp','С запасом · Онлайн','Оставь сопернику шары на столе, а себе — уверенную победу. Чем больше перевес, тем выше уровень достижения.','Победить с разницей ровно в 3 обычных шара.','bar','active',null,0,3,3,0,31017),
('bar-10-character','/achievements/bar/pool-shutout-v1.webp','Всухую · Вероника','Твой последний шар уходит в лузу, а все шары соперника ещё на сукне. Вот как выглядит сухая победа.','Выиграть всухую: у соперника ни одного зачтённого обычного шара.','bar','active',null,0,15,15,0,31018),
('bar-10-online','/achievements/bar/pool-shutout-v1.webp','Всухую · Онлайн','Твой последний шар уходит в лузу, а все шары соперника ещё на сукне. Вот как выглядит сухая победа.','Выиграть всухую: у соперника ни одного зачтённого обычного шара.','bar','active',null,0,15,15,0,31019),
('bar-11-character','/achievements/bar/pool-foul-v1.webp','Фол не помеха · Вероника','Фол уже случился, но партия продолжается. Верни себе стол и закончи её победным ударом.','Допустить собственный фол и всё равно выиграть партию.','bar','active',null,0,3,3,0,31020),
('bar-11-online','/achievements/bar/pool-foul-v1.webp','Фол не помеха · Онлайн','Фол уже случился, но партия продолжается. Верни себе стол и закончи её победным ударом.','Допустить собственный фол и всё равно выиграть партию.','bar','active',null,0,3,3,0,31021),
('bar-12-character','/achievements/bar/pool-rematch-v1.webp','Реванш в бильярд · Вероника','Вероника забрала прошлую партию. Оставайся у стола: следующий победный удар должен быть твоим.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31022),
('bar-12-online','/achievements/bar/pool-rematch-v1.webp','Реванш в бильярд · Онлайн','Вы уже знаете, как играет каждый. Вернись за стол к тому же сопернику и возьми своё в следующей партии.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31023),
('bar-13-character','/achievements/bar/checkers-wins-v1.webp','Победы в шашки · Арсенич','Арсенич смотрит на доску и ждёт твоего хода. Найди свой план и собери победы за шашечным столом.','Победить в этой игре 1 раз против персонажа «Арсенич».','bar','active',null,0,3,3,0,31024),
('bar-13-online','/achievements/bar/checkers-wins-v1.webp','Победы в шашки · Онлайн','За каждой шашкой стоит чужой замысел. Разгадывай планы живых соперников и доводи партии до победы.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31025),
('bar-14-character','/achievements/bar/checkers-streak-v1.webp','Победная серия в шашки · Арсенич','Арсенич снова расставляет шашки. Сохрани расчёт и продолжи серию побед над опытным соперником.','Выиграть 2 партии подряд против персонажа «Арсенич».','bar','active',null,0,5,5,0,31026),
('bar-14-online','/achievements/bar/checkers-streak-v1.webp','Победная серия в шашки · Онлайн','Новая доска, новый соперник, новый замысел. Проведи несколько партий подряд по своему победному плану.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31027),
('bar-15-character','/achievements/bar/checkers-multicapture-v1.webp','Цепная реакция · Арсенич','Первая взятая шашка открывает путь к следующей. Найди цепочку и пройди её одним непрерывным ходом.','Взять 2 фигуры соперника одним ходом.','bar','active',null,0,5,5,0,31028),
('bar-15-online','/achievements/bar/checkers-multicapture-v1.webp','Цепная реакция · Онлайн','Первая взятая шашка открывает путь к следующей. Найди цепочку и пройди её одним непрерывным ходом.','Взять 2 фигуры соперника одним ходом.','bar','active',null,0,5,5,0,31029),
('bar-16-character','/achievements/bar/checkers-crown-v1.webp','Коронация · Арсенич','Проведи шашку через всю доску. На последней линии она станет дамкой и получит простор для дальних ходов.','Довести свою шашку до превращения в дамку.','bar','active',null,0,3,3,0,31030),
('bar-16-online','/achievements/bar/checkers-crown-v1.webp','Коронация · Онлайн','Проведи шашку через всю доску. На последней линии она станет дамкой и получит простор для дальних ходов.','Довести свою шашку до превращения в дамку.','bar','active',null,0,3,3,0,31031),
('bar-17-character','/achievements/bar/checkers-kings-v1.webp','Против дамок · Арсенич','На доске появились дамки соперника, и привычные ходы стали опаснее. Перехвати инициативу и всё равно забери партию.','Выиграть партию, в которой у соперника была хотя бы одна дамка.','bar','active',null,0,5,5,0,31032),
('bar-17-online','/achievements/bar/checkers-kings-v1.webp','Против дамок · Онлайн','На доске появились дамки соперника, и привычные ходы стали опаснее. Перехвати инициативу и всё равно забери партию.','Выиграть партию, в которой у соперника была хотя бы одна дамка.','bar','active',null,0,5,5,0,31033),
('bar-18-character','/achievements/bar/checkers-survivors-v1.webp','Свои люди · Арсенич','Каждая сохранённая шашка пригодится в концовке. Доведи партию до победы и сбереги хотя бы половину своего состава.','Выиграть, потеряв не больше шести из двенадцати своих шашек.','bar','active',null,0,5,5,0,31034),
('bar-18-online','/achievements/bar/checkers-survivors-v1.webp','Свои люди · Онлайн','Каждая сохранённая шашка пригодится в концовке. Доведи партию до победы и сбереги хотя бы половину своего состава.','Выиграть, потеряв не больше шести из двенадцати своих шашек.','bar','active',null,0,5,5,0,31035),
('bar-19-character','/achievements/bar/checkers-rematch-v1.webp','Реванш в шашки · Арсенич','Арсенич выиграл прошлую встречу. Расставь шашки заново, учти его приёмы и ответь победой.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31036),
('bar-19-online','/achievements/bar/checkers-rematch-v1.webp','Реванш в шашки · Онлайн','Вы уже обменялись первой партией. Во второй встрече с тем же соперником найди ход, которого он не ждёт.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31037),
('bar-20-character','/achievements/bar/ochko-wins-v1.webp','Победы в очко · Григорий','Григорий уже раздаёт карты. Следи за счётом, вовремя останавливайся и собирай победы за его столом.','Победить в этой игре 1 раз против персонажа «Григорий».','bar','active',null,0,3,3,0,31038),
('bar-20-online','/achievements/bar/ochko-wins-v1.webp','Победы в очко · Онлайн','Карта открыта, решение за тобой. Чувствуй риск и выигрывай партии в очко у реальных игроков.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31039),
('bar-21-character','/achievements/bar/ochko-streak-v1.webp','Победная серия в очко · Григорий','Григорий снова берётся за колоду. Сохрани хладнокровие и продолжи победную серию за его столом.','Выиграть 2 партии подряд против персонажа «Григорий».','bar','active',null,0,5,5,0,31040),
('bar-21-online','/achievements/bar/ochko-streak-v1.webp','Победная серия в очко · Онлайн','Каждая раздача требует нового решения. Удержи удачный ритм на несколько победных партий подряд.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31041),
('bar-22-character','/achievements/bar/ochko-caught-v1.webp','За руку поймал · Григорий','Григорий объявил свой результат. Пересчитай карты внимательно: если он приписал лишнее, поймай его за руку.','Успешно разоблачить жульничество Григория.','bar','active',null,0,3,3,0,31042),
('bar-23-character','/achievements/bar/ochko-comeback-v1.webp','Последнее слово · Григорий','Перед последней раздачей ты позади. Сохрани холодную голову и переверни итоговый счёт в свою пользу.','Выиграть у Григория, уступая перед последней раздачей минимум на 1 очко.','bar','active',null,0,5,5,0,31043),
('bar-24-character','/achievements/bar/ochko-one-v1.webp','На очко впереди · Григорий','Все раздачи сыграны, карты лежат на столе. Всего одно очко перевеса — и эта напряжённая партия твоя.','Победить с итоговым перевесом ровно в одно очко за всю партию.','bar','active',null,0,5,5,0,31044),
('bar-24-online','/achievements/bar/ochko-one-v1.webp','На очко впереди · Онлайн','Все раздачи сыграны, карты лежат на столе. Всего одно очко перевеса — и эта напряжённая партия твоя.','Победить с итоговым перевесом ровно в одно очко за всю партию.','bar','active',null,0,5,5,0,31045),
('bar-25-character','/achievements/bar/ochko-rematch-v1.webp','Реванш в очко · Григорий','Прошлая партия осталась за Григорием. Прими новую раздачу и верни себе победу в следующей встрече.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31046),
('bar-25-online','/achievements/bar/ochko-rematch-v1.webp','Реванш в очко · Онлайн','Соперник только что выиграл у тебя. Сыграй с ним ещё раз и закончи следующую партию уже в свою пользу.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31047),
('bar-26-character','/achievements/bar/arm-wins-v1.webp','Победы в армрестлинге · Олег','Локти на стол, ладони в замок. Сойдись с Олегом в силовом поединке и собери свои победы.','Победить в этой игре 1 раз против персонажа «Олег».','bar','active',null,0,3,3,0,31048),
('bar-26-online','/achievements/bar/arm-wins-v1.webp','Победы в армрестлинге · Онлайн','С другой стороны стола живой соперник. Поймай его усилие, выбери момент и доведи поединок до победы.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31049),
('bar-27-character','/achievements/bar/arm-streak-v1.webp','Победная серия в армрестлинге · Олег','Олег снова протягивает руку через стол. Сохрани силу и расчёт на целую серию победных поединков.','Выиграть 2 партии подряд против персонажа «Олег».','bar','active',null,0,5,5,0,31050),
('bar-27-online','/achievements/bar/arm-streak-v1.webp','Победная серия в армрестлинге · Онлайн','Каждый новый соперник давит по-своему. Удержи победный ритм в нескольких схватках подряд.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31051),
('bar-28-character','/achievements/bar/arm-pin-v1.webp','Прижал! · Олег','Стрелка ещё движется, а рука соперника уже у стола. Дожми поединок до явной победы раньше сигнала времени.','Победить прижатием до окончания времени.','bar','active',null,0,3,3,0,31052),
('bar-28-online','/achievements/bar/arm-pin-v1.webp','Прижал! · Онлайн','Стрелка ещё движется, а рука соперника уже у стола. Дожми поединок до явной победы раньше сигнала времени.','Победить прижатием до окончания времени.','bar','active',null,0,3,3,0,31053),
('bar-29-character','/achievements/bar/arm-rematch-v1.webp','Реванш в армрестлинге · Олег','Олег оказался сильнее в прошлой схватке. Снова берись за его руку и найди свой победный момент.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31054),
('bar-29-online','/achievements/bar/arm-rematch-v1.webp','Реванш в армрестлинге · Онлайн','Руку отпустили, но счёты остались. Встреться с тем же соперником ещё раз и возьми реванш.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31055),
('bar-30-character','/achievements/bar/naval-wins-v1.webp','Победы в морской бой · Тимофей','Тимофей расставил флот и ждёт твоих координат. Найди его корабли и собирай победы на морской карте.','Победить в этой игре 1 раз против персонажа «Тимофей».','bar','active',null,0,3,3,0,31056),
('bar-30-online','/achievements/bar/naval-wins-v1.webp','Победы в морской бой · Онлайн','Чужой флот скрыт за клетками поля. Читай следы попаданий и отправляй корабли реальных соперников на дно.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31057),
('bar-31-character','/achievements/bar/naval-streak-v1.webp','Победная серия в морской бой · Тимофей','Новый флот Тимофея уже на карте. Сохрани расчёт и проведи серию победных морских сражений.','Выиграть 2 партии подряд против персонажа «Тимофей».','bar','active',null,0,5,5,0,31058),
('bar-31-online','/achievements/bar/naval-streak-v1.webp','Победная серия в морской бой · Онлайн','Новые расстановки, новые соперники. Найди победный курс и держись его несколько сражений подряд.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31059),
('bar-32-character','/achievements/bar/naval-submarine-v1.webp','Лодка вернулась · Тимофей','Подлодка ещё на плаву, а бой подходит к концу. Сохрани её до победы, даже если корпус уже получил повреждение.','Победить, сохранив свою подлодку на плаву. Повреждение допустимо.','bar','active',null,0,5,5,0,31060),
('bar-32-online','/achievements/bar/naval-submarine-v1.webp','Лодка вернулась · Онлайн','Подлодка ещё на плаву, а бой подходит к концу. Сохрани её до победы, даже если корпус уже получил повреждение.','Победить, сохранив свою подлодку на плаву. Повреждение допустимо.','bar','active',null,0,5,5,0,31061),
('bar-33-character','/achievements/bar/naval-hits-v1.webp','Пристрелялся · Тимофей','Попадание открывает следующую цель. Выбирай координаты точно и продли цепочку собственных выстрелов без промаха.','Сделать 3 попадания подряд в одной партии. Собственный промах обрывает серию.','bar','active',null,0,3,3,0,31062),
('bar-33-online','/achievements/bar/naval-hits-v1.webp','Пристрелялся · Онлайн','Попадание открывает следующую цель. Выбирай координаты точно и продли цепочку собственных выстрелов без промаха.','Сделать 3 попадания подряд в одной партии. Собственный промах обрывает серию.','bar','active',null,0,3,3,0,31063),
('bar-34-character','/achievements/bar/naval-first-v1.webp','С первого выстрела · Тимофей','Поле ещё чистое, следов выстрелов нет. Назови первую координату и сразу найди корабль соперника.','Попасть первым же собственным выстрелом в партии.','bar','active',null,0,2,2,0,31064),
('bar-34-online','/achievements/bar/naval-first-v1.webp','С первого выстрела · Онлайн','Поле ещё чистое, следов выстрелов нет. Назови первую координату и сразу найди корабль соперника.','Попасть первым же собственным выстрелом в партии.','bar','active',null,0,2,2,0,31065),
('bar-35-character','/achievements/bar/naval-rematch-v1.webp','Реванш в морской бой · Тимофей','Тимофей выиграл прошлый бой. Выставляй новый флот и ответь ему победой в следующем сражении.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31066),
('bar-35-online','/achievements/bar/naval-rematch-v1.webp','Реванш в морской бой · Онлайн','Ваши флоты уже встречались, и первый бой остался за соперником. Во второй встрече поменяй итог.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31067),
('bar-36-character','/achievements/bar/durak-wins-v1.webp','Победы в дурака · Мария','Мария тасует колоду и оставляет тебе место за столом. Найди подход к её игре и собирай победные партии.','Победить в этой игре 1 раз против персонажа «Мария».','bar','active',null,0,3,3,0,31068),
('bar-36-online','/achievements/bar/durak-wins-v1.webp','Победы в дурака · Онлайн','На руках карты, напротив — живые соперники. Выбирай момент для атаки и заканчивай партии победителем.','Победить в этой игре 1 раз против реальных игроков.','bar','active',null,0,3,3,0,31069),
('bar-37-character','/achievements/bar/durak-streak-v1.webp','Победная серия в дурака · Мария','Мария предлагает новую раздачу. Продолжи свою серию: отбивайся внимательно и вовремя освобождай руку.','Выиграть 2 партии подряд против персонажа «Мария».','bar','active',null,0,5,5,0,31070),
('bar-37-online','/achievements/bar/durak-streak-v1.webp','Победная серия в дурака · Онлайн','Каждая раздача начинает новую историю. Проведи несколько победных партий подряд с реальными игроками.','Выиграть 2 партии подряд против реальных игроков.','bar','active',null,0,5,5,0,31071),
('bar-38-character','/achievements/bar/durak-trumps-v1.webp','Не в козырях счастье · Мария','Козырей досталось мало, и обычные карты становятся особенно важны. Разыграй слабую руку так, чтобы победа осталась за тобой.','Выиграть, получив за всю партию не больше 5 козырей: из раздачи, добора и взятых со стола карт.','bar','active',null,0,5,5,0,31072),
('bar-38-online','/achievements/bar/durak-trumps-v1.webp','Не в козырях счастье · Онлайн','Козырей досталось мало, и обычные карты становятся особенно важны. Разыграй слабую руку так, чтобы победа осталась за тобой.','Выиграть, получив за всю партию не больше 5 козырей: из раздачи, добора и взятых со стола карт.','bar','active',null,0,5,5,0,31073),
('bar-39-character','/achievements/bar/durak-epaulettes-v1.webp','Погоны · Мария','Две шестёрки дождались своего часа. Закончи ими победную партию и оставь сопернику погоны на память.','Закончить победную партию двумя шестёрками.','bar','active',null,0,10,10,0,31074),
('bar-39-online','/achievements/bar/durak-epaulettes-v1.webp','Погоны · Онлайн','Две шестёрки дождались своего часа. Закончи ими победную партию и оставь сопернику погоны на память.','Закончить победную партию двумя шестёрками.','bar','active',null,0,10,10,0,31075),
('bar-40-character','/achievements/bar/durak-defense-v1.webp','Непробиваемый · Мария','Карты летят на стол одна за другой. Подбери ответ на каждую и отправь весь розыгрыш в отбой.','За одну защиту отбить 2 атакующие карты и отправить весь розыгрыш в отбой.','bar','active',null,0,3,3,0,31076),
('bar-40-online','/achievements/bar/durak-defense-v1.webp','Непробиваемый · Онлайн','Карты летят на стол одна за другой. Подбери ответ на каждую и отправь весь розыгрыш в отбой.','За одну защиту отбить 2 атакующие карты и отправить весь розыгрыш в отбой.','bar','active',null,0,3,3,0,31077),
('bar-41-character','/achievements/bar/durak-no-take-v1.webp','Не беру · Мария','Рука пополняется из колоды, а со стола брать не приходится. Пройди всю партию с надёжной защитой и победи.','Выиграть партию, ни разу не взяв карты со стола.','bar','active',null,0,10,10,0,31078),
('bar-41-online','/achievements/bar/durak-no-take-v1.webp','Не беру · Онлайн','Рука пополняется из колоды, а со стола брать не приходится. Пройди всю партию с надёжной защитой и победи.','Выиграть партию, ни разу не взяв карты со стола.','bar','active',null,0,10,10,0,31079),
('bar-42-character','/achievements/bar/durak-full-hand-v1.webp','Всё на стол · Мария','На руках полная шестёрка, на столе начинается твоя атака. Подкинь всё до последней карты за один розыгрыш.','Начать атакующий розыгрыш с шестью картами на руках и выложить все шесть за этот розыгрыш.','bar','active',null,0,5,5,0,31080),
('bar-42-online','/achievements/bar/durak-full-hand-v1.webp','Всё на стол · Онлайн','На руках полная шестёрка, на столе начинается твоя атака. Подкинь всё до последней карты за один розыгрыш.','Начать атакующий розыгрыш с шестью картами на руках и выложить все шесть за этот розыгрыш.','bar','active',null,0,5,5,0,31081),
('bar-43-character','/achievements/bar/durak-rematch-v1.webp','Реванш в дурака · Мария','Мария выиграла прошлую партию. Оставайся за столом и забери следующую раздачу себе.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31082),
('bar-43-online','/achievements/bar/durak-rematch-v1.webp','Реванш в дурака · Онлайн','Прошлая партия закончилась в пользу соперника. В следующей встрече с ним разыграй свои карты лучше.','После поражения выиграть следующую партию в этой игре у того же соперника.','bar','active',null,0,5,5,0,31083),
('bar-44-social','/achievements/bar/bar-regular-v1.webp','Завсегдатай','Загляни в «4-й период» после матча: сыграть партию, перекинуться словом, встретить знакомых. Постепенно бар становится привычным местом.','Посетить бар в 1 день: завершить игру или отправить сообщение любому персонажу. Пропуски не сбрасывают прогресс.','bar','active',null,0,2,2,0,31084),
('bar-45-social','/achievements/bar/meet-igor-v1.webp','Познакомиться с Игорем','У стойки всегда найдётся повод поговорить о хоккее. Начни разговор с Игорем и познакомься с барменом «4-го периода».','Начать разговор с персонажем «Игорь»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31085),
('bar-46-social','/achievements/bar/meet-daria-v1.webp','Познакомиться с Дарьей','Дарья работает в баре и охотно поддерживает разговор. Подойди познакомиться и перекинься с ней первыми словами.','Начать разговор с персонажем «Дарья»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31086),
('bar-47-social','/achievements/bar/meet-veronika-v1.webp','Познакомиться с Вероникой','Вероника следит за порядком в «4-м периоде». Найди минуту познакомиться с управляющей бара.','Начать разговор с персонажем «Вероника»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31087),
('bar-48-social','/achievements/bar/meet-grigory-v1.webp','Познакомиться с Григорием','Григорий любит карточный стол и хороший разговор. Познакомься с ним прежде, чем спорить о следующей раздаче.','Начать разговор с персонажем «Григорий»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31088),
('bar-49-social','/achievements/bar/meet-oleg-v1.webp','Познакомиться с Олегом','Олег отвечает за спокойствие вокруг стадиона. Поздоровайся и начни разговор с человеком, который привык говорить по делу.','Начать разговор с персонажем «Олег»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31089),
('bar-50-social','/achievements/bar/meet-arsenich-v1.webp','Познакомиться с Арсеничем','У Арсенича за плечами большой опыт и свой взгляд на хоккей. Присядь рядом и начни ваше знакомство.','Начать разговор с персонажем «Арсенич»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31090),
('bar-51-social','/achievements/bar/meet-timofey-v1.webp','Познакомиться с Тимофеем','Тимофей руководит службой стадиона, а в баре отдыхает от дел. Подойди познакомиться и найди тему для первого разговора.','Начать разговор с персонажем «Тимофей»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31091),
('bar-52-social','/achievements/bar/meet-maria-v1.webp','Познакомиться с Марией','Мария умеет поддержать беседу и составить компанию за карточным столом. Начни знакомство с простого разговора.','Начать разговор с персонажем «Мария»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31092),
('bar-53-social','/achievements/bar/meet-elina-v1.webp','Познакомиться с Элиной','У Элины свой бар и плотный рабочий день. Представься хозяйке «4-го периода» и начни знакомство по делу.','Начать разговор с персонажем «Элина»: отправить сообщение и получить ответ.','bar','active',null,0,3,3,0,31093),
('bar-54-social','/achievements/bar/bar-card-v1.webp','Стать членом клуба','Знакомый стол, больше партий и времени на разговоры. Оформи клубную карту, чтобы чаще оставаться в «4-м периоде».','Купить или продлить клубную карту после запуска заданий.','bar','active',null,0,10,10,0,31094);
