-- New bar tasks start with this migration; no historical gameplay is imported.
alter table achievements drop constraint achievements_category_check;
alter table achievements add constraint achievements_category_check check
 (category in ('career','daily','training','duel','tournament','shop','rating','level','fans','bar'));
create table bar_achievement_launch(singleton boolean primary key default true check(singleton),started_at timestamptz not null default now());
create table bar_achievement_events(user_id uuid not null references users(id) on delete cascade,event_key text not null,occurred_at timestamptz not null,primary key(user_id,event_key));
create table bar_achievement_totals(user_id uuid not null references users(id) on delete cascade,achievement_id text not null references achievements(id),value integer not null check(value>=0),updated_at timestamptz not null,primary key(user_id,achievement_id));
create table bar_achievement_state(user_id uuid not null references users(id) on delete cascade,key text not null,state jsonb not null,primary key(user_id,key));
create table bar_achievement_days(user_id uuid not null references users(id) on delete cascade,day date not null,primary key(user_id,day));
create table bar_maria_matches(id uuid primary key,user_id uuid not null references users(id) on delete cascade,state jsonb not null,deadline_at timestamptz,ended_at timestamptz,started_at timestamptz not null default now());
create index bar_maria_matches_active on bar_maria_matches(user_id) where ended_at is null;
create unique index bar_maria_matches_one_active on bar_maria_matches(user_id) where ended_at is null;
create index bar_maria_matches_due on bar_maria_matches(deadline_at) where ended_at is null;
alter table bar_computer_card_history drop constraint bar_computer_card_history_provenance_check;
alter table bar_computer_card_history add constraint bar_computer_card_history_provenance_check check(provenance in ('client_reported','server'));
